   // variables `first` and `second` which will be of `float` type.\n    io:println(first);\n    io:println(second);\n\n    // The rest of the values will be bound to `others`, which will be of `float[]` type.\n    io:println(others);\n}\n\nfunction getScores() returns float[4] {\n    return [1.2, 2.3, 3.4, 4.5];\n}\n"];var Qe=['import ballerina/io;\n\ntype Person record {|\n    int id;\n    string fname;\n    string lname;\n|};\n\npublic function main() {\n    // `_` is used to ignore the value of the `id` field.\n    // The values of the `fname` and `lname` fields are bound to the `firstName` and\n    // `lastName` variable names.\n    Person {id: _, fname: firstName, lname: lastName} = getPerson();\n    io:println(firstName + " " + lastName);\n\n    // The `fname` and `lname` fields do not have explicitly defined variable names.\n    // `{fname, lname}` is the same as `{fname: fname, lname: lname}`.\n    // The `id` field is ignored as it is not bound to a variable.\n    Person {fname, lname} = getPerson();\n    io:println(fname + " " + lname);\n\n    string givenName;\n    string surname;\n\n    // This destructures and assigns the values of the fields in the destructed record\n    // to the variable references.\n    // The values of the `fname` and `lname` fields are assigned to the `givenName` and\n    // `surname` variables.\n    {fname: givenName, lname: surname} = getPerson();\n    io:println(givenName + " " + surname);\n}\n\nfunction getPerson() returns Person {\n    Person person = {id: 1001, fname: "Anne", lname: "Frank"};\n    return person;\n}\n'];var Ke=['import ballerina/io;\n\ntype Person record {\n    int id;\n    string fname;\n    string lname;\n};\n\npublic function main() {\n    // The value of the `id` field is ignored using `_`.\n    // The value of the `fname` field is matched with the `firstName` variable.\n    // `...otherDetails` is a rest parameter. The remaining fields that have not been matched\n    // are matched with `...otherDetails`.\n    Person {id: _, fname: firstName, ...otherDetails} = getPerson();\n    io:println(firstName);\n\n    // The type of `otherDetails` is a `record` holding the remaining fields.\n    record {|string lname; anydata...;|} details = otherDetails;\n    io:println(details);\n\n    string fname;\n    record {|string lname; anydata...;|} otherInfo;\n\n    // The values of the fields in the destructed record are assigned to the variable references.\n    // The value of the `fname` field is assigned to the `fname` variable.\n    // The remaining field values that have not been matched are assigned to `...otherInfo`.\n    {fname, ...otherInfo} = getPerson();\n    io:println(fname);\n    io:println(otherInfo);\n}\n\nfunction getPerson() returns Person {\n    Person person = {id: 1001, fname: "Anne", lname: "Frank", "age": 24, "country": "UK"};\n    return person;\n}\n'];var Xe=['import ballerina/io;\n\ntype SampleErrorData record {|\n    int code;\n    string reason;\n|};\n\ntype SampleError error<SampleErrorData>;\n\npublic function main() {\n    // The value of the error message is ignored by using `_`.\n    // The value of the error cause is set to the `cause` variable.\n    // The values in the error detail mapping is set to the `code` and `reason` variables.\n    var error(_, cause, code = code, reason = reason) = getSampleError();\n    io:println("Cause: ", cause);\n    io:println("Info: ", code);\n    io:println("Fatal: ", reason);\n\n    // The values in the cause and detail mapping are ignored in this binding.\n    SampleError error(message2) = getSampleError();\n    io:println("Message: ", message2);\n\n    error? errorCause;\n    int errorCode;\n\n    // The error value is destructured and assigned to the variable references.\n    // The values of the error cause and `code` are assigned to the `errorCause` and `errorCode` variables.\n    // The error message and the `reason` field in the detail mapping are ignored.\n    error(_, errorCause, code = errorCode) = getSampleError();\n    io:println("Cause: ", errorCause);\n    io:println("Code: ", errorCode);\n}\n\nfunction getSampleError() returns SampleError {\n    return error("Transaction Failure", error("Database Error"), code = 20,\n                            reason = "deadlock condition");\n}\n'];var Ye=['import ballerina/io;\n\ntype SampleErrorData record {|\n    int code;\n    string reason;\n|};\n\ntype SampleError error<SampleErrorData>;\n\npublic function main() {\n    // The detail mapping can be destructured using a rest parameter.\n    // `details` is of type `map<string|boolean>` having the `code` and `reason` fields.\n    var error(message, ...details) = getSampleError();\n    io:println("Message: ", message);\n\n    map<int|string> detailsMap = details;\n    io:println("Details: ", detailsMap);\n\n    // Here, the `...filteredDetails` rest parameter contains only the detail fields\n    // that are not matched.\n    var error(_, code = code, ...filteredDetails) = getSampleError();\n    io:println("Code: ", code);\n    io:println("Filtered Details: ", filteredDetails);\n\n    map<int|string> moreDetails;\n\n    // The detail mapping can be destructured into a `map<int|string>` typed variable\n    // by using a rest parameter.\n    error(_, ...moreDetails) = getSampleError();\n    io:println("All Details: ", moreDetails);\n}\n\nfunction getSampleError() returns SampleError {\n    return error("Transaction Failure", error("Database Error"), code = 20,\n                            reason = "deadlock condition");\n}\n'];var en=['import ballerina/io;\n\ntype Person record {\n    int id;\n    string fname;\n    string lname;\n};\n\npublic function main() {\n    // A typed list binding followed by `=` in which the values of the list members are bound to\n    // the `name` and `age` variables in the binding.\n    [string, int] [name, age] = getPersonInfo();\n    io:println(name, " ", age);\n\n    // The same can be written using `var`.\n    var [personName, personAge] = getPersonInfo();\n    io:println(personName, " ", personAge);\n\n    // Other binding patterns can also be used as such.\n    // Here, a typed mapping binding is followed by `=` in which the values of the record fields\n    // are bound to the `id`, `fname`, and `lname` variables of the binding.\n    Person {id, fname, lname} = getPerson();\n    io:println(id, " ", fname, " ", lname);\n}\n\nfunction getPersonInfo() returns [string, int] {\n    return ["John", 30];\n}\n\nfunction getPerson() returns Person {\n    return {id: 1001, fname: "Anne", lname: "Frank"};\n}\n'];var nn=['import ballerina/io;\n\npublic function main() {\n   do {\n       _ = check int:fromString("Hello");\n       // A typed capture binding pattern is used with an `on fail` clause.\n       // It matches the associated error value in the clause and binds the value\n       // to the `err` variable.\n   } on fail error err {\n       io:println(err.message());\n   }\n}\n'];var tn=['import ballerina/io;\n\ntype Person record {|\n    int id;\n    string fname;\n    string lname;\n|};\n\npublic function main() {\n    int sum = 0;\n    string names = "";\n    [string, int][] personInfoList = getPersonInfo();\n    Person[] personList = getPersonList();\n\n    // The values in the `personInfoList` is bound to the `[name, age]` list binding for each iteration.\n    foreach [string, int] [name, age] in personInfoList {\n        names += " " + name;\n        sum += age;\n    }\n    io:println("Average age of", names, ": ", sum / 3);\n\n    // The mapping binding pattern used in the `from` clause binds the record fields with the\n    // specified variable names for every value in the `personList`.\n    var personInfo = from var {id: personId, fname: firstName, lname: lastName} in personList\n        select {\n            id: personId,\n            name: firstName + " " + lastName\n        };\n    io:println(personInfo);\n}\n\nfunction getPersonInfo() returns [string, int][] {\n    return [["John", 30], ["Anne", 24], ["Mike", 21]];\n}\n\nfunction getPersonList() returns Person[] {\n    return [{id: 1001, fname: "Anne", lname: "Frank"}, {id: 1002, fname: "John", lname: "Hardy"}];\n}\n'];var sn=['import ballerina/io;\n\nfunction matchCommand(any commands) {\n    match commands {\n        var [show] => {\n            io:println(show);\n        }\n        // The list binding pattern below binds lists that contain three list items\n        // where the third element in the list is the boolean value `true`.\n        var [remove, all, isDir] if isDir is true => {\n            io:println(remove, " directories ", all);\n        }\n        // The list binding pattern below binds lists that contain three list items.\n        var [remove, all, _] => {\n            io:println(remove, " files ", all);\n        }\n        // The list binding pattern below binds lists that contain two list items,\n        // in which the second list item is also a list of two items.\n        var [copy, [file1, file2]] => {\n            io:println(copy, " ", file1, " into ", file2);\n        }\n        _ => {\n            io:println("Unrecognized command.");\n        }\n    }\n}\n\n\npublic function main() {\n    matchCommand(["Show"]);\n    matchCommand(["Remove", "*", true]);\n    matchCommand(["Remove", "f.txt", false]);\n    matchCommand(["Copy", ["a.bal", "b.bal"]]);\n    matchCommand(1);\n}\n'];var an=['import ballerina/io;\n\ntype Time record {\n    int hours;\n    int minutes;\n};\n\ntype Day record {\n    Time t;\n};\n\nfunction matchTime1(Time pair) {\n    match pair {\n        // The binding pattern below matches the mappings that contain at least the fields with \n        // the `hours` and `seconds` keys. The values of these fields can be accessed via the \n        // `hours` and `seconds` variables within this block.\n        var {hours, minutes} => {\n            io:println(hours, ", ", minutes);\n        }\n    }\n}\n\nfunction matchTime2(Time time) {\n    match time {\n        // The binding pattern below  has a rest binding pattern to capture the additional \n        // fields that may be specified in the open record value assigned to the `time` variable.\n        // Type of the `rest` variable can be considered a map of `anydata`. However, it cannot \n        // contain the `hours` or `minutes` keys.\n        var {hours, minutes, ...rest} => {\n            io:println(hours, ", ", minutes, ", ", rest);\n        }\n    }\n}\n\nfunction matchTime3(Day day) {\n    match day {\n        // The pattern below matches a mapping that has a field with the `t`key\n        // and a value, which is another mapping that contains at least the fields \n        // with the `hours` and `minutes` keys.\n        var {t: {hours, minutes}} => {\n            io:println(hours, ", ", minutes);\n        }\n    }\n}\n\nfunction matchTime4(Time time) {\n    match time {\n        // The binding pattern below has a rest binding pattern to capture the additional \n        // fields that may be specified in the open record value assigned to the `time` variable.\n        // The condition here checks whether the open record has the field `meridiem`.\n        var {hours, minutes, ...rest}\n                if rest["meridiem"] !is () && rest["meridiem"] == "PM" => {\n            io:println(hours + 12, ", ", minutes);\n        }\n        _ => {\n            io:println(time.hours, ", ", time.minutes);\n        }\n    }\n}\n\npublic function main() {\n    Time time = {hours: 3, minutes: 20, "seconds": 40, "milli-seconds": 500};\n    matchTime1(time);\n    matchTime2(time);\n\n    Day day = {t: time};\n    matchTime3(day);\n\n    Time time2 = {hours: 11, minutes: 21, "seconds": 52, "meridiem": "PM"};\n    matchTime4(time2);\n    matchTime4(time);\n}\n'];var rn=['import ballerina/io;\n\ntype DatabaseErrorDetail record {|\n    int code;\n    string reason;\n|};\n\ntype NetworkErrorDetail record {|\n    string \'type;\n    string phase;\n    int elapsedTime;\n|};\n\ntype DatabaseError error<DatabaseErrorDetail>;\n\ntype NetworkError error<NetworkErrorDetail>;\n\nconst ERROR = "Generic Error";\n\nfunction errorMatch(error e) {\n    match e {\n        // This error binding pattern matches a `DatabaseError` type error value and\n        // binds its `code` detail mapping to the `code` variable.\n        var error DatabaseError(code = code) => {\n            io:println("Matched DatabaseError with code:", code);\n        }\n        // This error binding pattern matches an error value with an `ERROR` error message and\n        // binds its `code` detail mapping to the `code` variable.\n        var error(ERROR, code = code) => {\n            io:println("Matched Generic Error with message:", ERROR, " and code:", code);\n        }\n        // This error binding pattern matches the value of the error message in an error with the `message`\n        // variable, the value of the `type` field in the detail mapping is matched with the `errorType` variable, and\n        // the `...otherDetails` rest parameter is matched with the remaining detail fields.\n        var error(message, \'type = errorType, ...otherDetails) => {\n            io:println("Matched NetworkError with message:", message, ", type:", errorType, ", phase:",\n                    otherDetails["phase"], " and elapsedTime:", otherDetails["elapsedTime"]);\n        }\n    }\n}\n\npublic function main() {\n    error e1 = error("Generic Error", code = 20);\n    DatabaseError e2 = error("Database Error", code = 2, reason = "connection failure");\n    NetworkError e3 = error NetworkError("Bad Request", \'type = "http error", phase = "application",\n                                    elapsedTime = 338);\n    errorMatch(e1);\n    errorMatch(e2);\n    errorMatch(e3);\n}\n'];var ln=['import ballerina/io;\n \ntype Employee record {|\n   \t// The key must be read-only.\n   \treadonly string name;\n   \tint salary;\n|};\n \npublic function main() {\n   \t// Creates a `table` with members of the `Employee` type in which each\n   \t// member is uniquely identified using their `name` field.\n   \ttable<Employee> key(name) employees = table [\n   \t    { name: "John", salary: 100 },\n   \t    { name: "Jane", salary: 200 }\n   \t];\n\t\n   \t// Since the key is already available, the `put` method updates the entry with the new `salary`.\n   \t// If the key is not available, `put` will function the same as `add`.\n   \temployees.put({name: "John", salary: 320});\n   \tio:println(employees);\n\t\n   \t// As the key is not available, the `add` method appends the new entry.\n   \t// If the key is available, the operation results in a panic.\n   \temployees.add({name: "Sam", salary: 150});\n   \tio:println(employees);\n\t\n   \t// Retrieves the `Employee` member with `"Fred"` as the value of the key.\n   \tEmployee? e = employees["Fred"];\n   \tio:println(e is ());\n\t\n   \t// Iterates over the rows of `employees` in the specified order.\n   \tforeach Employee employee in employees {\n   \t    employee.salary += 102;\n   \t}\n   \t_ = employees.remove("John");\n\t\n   \tio:println(employees);\n}\n'];var on=['import ballerina/io;\n \ntype Employee record {|\n   \treadonly string name;\n   \tint salary;\n|};\n \npublic function main() {\n   \t// Creates a `table` with members of the `Employee` type in which each\n   \t// member is uniquely identified using their `name` field.\n   \ttable<Employee> key(name) t1 = table [\n   \t    { name: "John", salary: 100 },\n   \t    { name: "Jane", salary: 200 }\n   \t];\n   \tio:println(t1);\n\t\n   \t// A table can be declared without a key.\n   \ttable<Employee> t2 = table [\n   \t    { name: "John", salary: 100 },\n   \t    { name: "Jane", salary: 200 }\n   \t];\n   \tio:println(t2);\n\t\n   \t// A table can also be declared with a type parameter as the key type.\n   \ttable<Employee> key<string> t3 = table key(name) [\n   \t    { name: "John", salary: 100 },\n   \t    { name: "Jane", salary: 200 }\n   \t];\n   \tio:println(t3);\n}\n'];var cn=['import ballerina/io;\n\ntype Employee record {\n    readonly string firstName;\n    readonly string lastName;\n    int salary;\n};\n\npublic function main() {\n    // `employees` has a key sequence with the `firstName` and `lastName` fields.\n    table<Employee> key(firstName, lastName) employees = table [\n            {firstName: "John", lastName: "Smith", salary: 100},\n            {firstName: "John", lastName: "Bloggs", salary: 200}\n        ];\n\n    // The key sequence provides keyed access to members of the `table`.\n    Employee? e = employees["John", "Bloggs"];\n    io:println(e);\n\n    // `employees` has a key sequence with the `firstName` and `lastName` fields.\n    table<Employee> key<[string, string]> employees2 = table key(firstName, lastName) [\n            {firstName: "John", lastName: "Smith", salary: 100},\n            {firstName: "John", lastName: "Bloggs", salary: 200}\n        ];\n\n    e = employees2["John", "Smith"];\n    io:println(e);\n}\n'];var dn=['import ballerina/io;\n\ntype Employee record {\n    readonly record {\n        string first;\n        string last;\n    } name;\n    int salary;\n};\n\npublic function main() {\n    //In the key field, the `name` is of the `record` type.\n    table<Employee> key(name) t = table [\n            {name: {first: "John", last: "Smith"}, salary: 100},\n            {name: {first: "Fred", last: "Bloggs"}, salary: 200}\n        ];\n\n    Employee? e = t[{first: "Fred", last: "Bloggs"}];\n    io:println(e);\n\n    record {|string first; string last;|} n = {first: "Sam", last: "Smith"};\n    // Make the key immutable using `cloneReadOnly()`.\n    t.add({name: n.cloneReadOnly(), salary: 23});\n    io:println(t);\n}\n'];var hn=['import ballerina/io;\n \npublic function main() {\n    int[] nums = [1, 2, 3, 4];\n \n    // The `from` clause works similar to a `foreach` statement.\n    int[] numsTimes10 = from var i in nums\n                        // The `select` clause is evaluated for each iteration.\n                        select i * 10;\n    io:println(numsTimes10);\n \n    // A `where` clause can be used to filter iterable values.\n    // It can occur multiple times anywhere between a `from` and `select` clause.\n    // This will pass the frame to the `select` clause only if `i % 2 == 0` is true.\n    int[] evenNums = from int i in nums\n                     where i % 2 == 0\n                     select i;\n    io:println(evenNums);\n \n    // The `order by` clause can be used to sort the result in \n    // `ascending` or `descending` order.\n    int[] numsReversed = from int i in nums\n                         order by i descending\n                         select i;\n    io:println(numsReversed);\n \n    // Iterating a string value using the query expression.\n    string languageName = "Ballerina";\n    string newName = from var char in languageName\n                     select char + char;\n \n    io:println(newName);\n}\n'];var xn=['import ballerina/io;\n\ntype Employee record {\n    string firstName;\n    string lastName;\n    decimal salary;\n};\n\npublic function main() {\n    Employee[] employees = [\n        {firstName: "Jones", lastName: "Welsh", salary: 1000.00},\n        {firstName: "Anne", lastName: "Frank", salary: 5000.00},\n        {firstName: "Rocky", lastName: "Irving", salary: 6000.00},\n        {firstName: "Anne", lastName: "Perera", salary: 3000.00},\n        {firstName: "Jermaine", lastName: "Perera", salary: 4000.00},\n        {firstName: "Rocky", lastName: "Puckett", salary: 6000.00},\n        {firstName: "Jermaine", lastName: "Kent", salary: 4000.00}\n    ];\n\n    Employee[] sorted = from var e in employees\n                        // The `order by` clause sorts the output items based on the given \n                        // `order-key` and the `order-direction`.\n                        // The `order-key` must be an ordered type.\n                        // The `order-direction` is `ascending` if not specified explicitly.\n                        order by e.firstName ascending, e.lastName descending\n                        select e;\n\n    foreach Employee e in sorted {\n        io:println(e.firstName, " ", e.lastName);\n    }\n}\n'];var pn=['import ballerina/io;\n\ntype Student record {|\n    string first;\n    string last;\n    int mathematics;\n    int english;\n|};\n\npublic function main() {\n    Student[] students = [\n        {first: "Melina", last: "Kodel", mathematics: 79, english: 83},\n        {first: "Tom", last: "Riddle", mathematics: 69, english: 45}\n    ];\n\n    int[] names = from var student in students\n                  // The `let` clause binds the variables.\n                  let int sum = (student.mathematics + student.english)\n                  where sum > 0\n                  let int avg = sum / 2\n                  select avg;\n\n    io:println(names);\n\n    // The `let` clause supports multiple variable declarations separated by `,`.\n    names = from var student in students\n                   let int sum = (student.mathematics + student.english), int avg = sum / 2\n                   where sum > 0\n                   select avg;\n\n    io:println(names);\n}\n'];var un=['import ballerina/io;\n\ntype Employee record {\n    string firstName;\n    string lastName;\n    decimal salary;\n};\n\npublic function main() {\n    Employee[] employees = [\n        {firstName: "Jones", lastName: "Welsh", salary: 1000.00},\n        {firstName: "Anne", lastName: "Frank", salary: 5000.00},\n        {firstName: "Michael", lastName: "Cain", salary: 10000.00},\n        {firstName: "Tom", lastName: "Hiddleston", salary: 2000.00}\n    ];\n\n    Employee[] top3 = from var e in employees\n                      order by e.salary descending\n                      // The `limit` clause limits the number of output items to 3.\n                      limit 3\n                      select e;\n\n    foreach var emp in top3 {\n        io:println(emp);\n    }\n}\n'];var mn=['import ballerina/io;\n\ntype User record {|\n    int id;\n    string name;\n|};\n\ntype Login record {|\n    int userId;\n    string time;\n|};\n\npublic function main() {\n    User[] users = [\n        {id: 1234, name: "Keith"},\n        {id: 6789, name: "Anne"}\n    ];\n\n    Login[] logins = [\n        {userId: 6789, time: "20:10:23"},\n        {userId: 1234, time: "10:30:02"},\n        {userId: 3987, time: "12:05:00"}\n    ];\n\n    // Inner equijoin.\n    string[] joinResult = from var login in logins\n                          // The `join` clause iterates any iterable value similarly to the\n                          // `from` clause.\n                          join var user in users\n                          // The `on` condition is used to match the `login` with the\n                          // `user` based on the `userId`.\n                          // The iteration is skipped when the condition is not satisfied.\n                          on login.userId equals user.id\n                          select string `${user.name} : ${login.time}`;\n\n    io:println(joinResult);\n\n    // Outer equijoin.\n    string[] outerEquijoin = from var login in logins\n                             outer join var user in users\n                             // If there is no matching pair for all members in the `users`,\n                             // then, the `user` will be `()`,\n                             // and the join-on-condition will be skipped.\n                             on login.userId equals user is () ? () : user.id\n                             select string `${user is () ? "New user" : user.name} : ${login.time}`;\n\n    io:println(outerEquijoin);\n}\n'];var bn=['import ballerina/io;\n\ntype Department record {|\n   int id;\n   string name;\n|};\n\ntype Person record {|\n   int id;\n   string fname;\n   string lname;\n|};\n\ntype DeptPerson record {|\n   string fname;\n   string? dept;\n|};\n\npublic function main() {\n    Person p1 = {id: 1, fname: "Alex", lname: "George"};\n    Person p2 = {id: 2, fname: "John", lname: "Fonseka"};\n    Person p3 = {id: 3, fname: "Ted", lname: "Perera"};\n\n    Department d1 = {id: 1, name:"HR"};\n    Department d2 = {id: 2, name:"Operations"};\n\n    Person[] personList = [p1, p2, p3];\n    Department[] deptList = [d1, d2];\n\n    DeptPerson[] deptPersonList =\n       from Person person in personList\n       // The `outer join` clause performs a left outer equijoin.\n       // For the records for which there is no matching record\n       // on the `deptList`, the resulting record will contain `nil` fields.\n       outer join var dept in deptList\n       on person.id equals dept?.id\n       select {\n           fname : person.fname,\n           dept : dept?.name\n       };\n\n    io:println(deptPersonList);\n}\n'];var jn=['import ballerina/io;\n\ntype Employee record {|\n    readonly int id;\n    string firstName;\n    string lastName;\n    int salary;\n|};\n\npublic function main() {\n    table<Employee> key(id) employees = table [\n            {id: 1, firstName: "John", lastName: "Smith", salary: 100},\n            {id: 2, firstName: "Jane", lastName: "Smith", salary: 150},\n            {id: 4, firstName: "Fred", lastName: "Bloggs", salary: 200},\n            {id: 7, firstName: "Bobby", lastName: "Clark", salary: 300},\n            {id: 9, firstName: "Cassie", lastName: "Smith", salary: 250}\n        ];\n\n    // Since the contextually-expected type for the query expression is `int[]`,\n    // the evaluation of the query expression will result in an integer array.\n    int[] salaries = from var emp in employees\n                     select emp.salary;\n    io:println(salaries);\n\n    // The query expression creates a table based on the contextually-expected type.\n    table<Employee> highPaidEmployees = from Employee emp in employees\n                             where emp.salary > 180\n                             order by emp.firstName\n                             select emp;\n\n    foreach Employee emp in highPaidEmployees {\n        io:println(emp.firstName, " ", emp.lastName);\n    }\n}\n'];var gn=['import ballerina/io;\n\ntype Employee record {|\n    readonly int id;\n    string firstName;\n    string lastName;\n    int salary;\n|};\n\npublic function main() {\n    table<Employee> key(id) employees = table [\n            {id: 1, firstName: "John", lastName: "Smith", salary: 100},\n            {id: 2, firstName: "Fred", lastName: "Bloggs", salary: 2000}\n        ];\n\n    // The `key(id)` key specifier specifies the key sequence of the constructed table.\n    // `select` clause must emit values belonging to `map<any|error>`.\n    var highPaidEmployees = table key(id) from var e in employees\n                            where e.salary >= 1000\n                            select e;\n    io:println(highPaidEmployees);\n\n    // A table can also be constructed by providing the contextually expected type.\n    // `table<Employee>` is the contextually expected type.\n    // `select` clause must emit values belonging to `Employee`.\n    table<Employee> highPaidEmployees2 = from var e in employees\n                                         where e.salary >= 1000\n                                         select e;\n    io:println(highPaidEmployees2);\n}\n'];var fn=['import ballerina/io;\n\ntype Student record {|\n    readonly int id;\n    string firstName;\n    string lastName;\n    int score;\n|};\n\npublic function main() returns error? {\n    table<Student> key(id) students = table [\n            {id: 1, firstName: "John", lastName: "Smith", score: 100},\n            {id: 2, firstName: "Jane", lastName: "Smith", score: 150},\n            {id: 4, firstName: "Fred", lastName: "Bloggs", score: 200},\n            {id: 7, firstName: "Bobby", lastName: "Clark", score: 300},\n            {id: 9, firstName: "Cassie", lastName: "Smith", score: 250}\n        ];\n\n    // The type of the value in the `select` clause must belong to the\n    // `[string, T]` tuple type, where the type of the constructed value is `map<T>`. \n    map<int> studentScores = map from var student in students\n                        select [student.firstName, student.score];\n    io:println(studentScores);\n}\n'];var vn=['import ballerina/io;\n\nstring[] students = ["John", "Mike", "Mia"];\n \npublic function main() {\n    int[] studentIds = [0, 1, 2];\n    // The `getStudentAPI()` is not invoked at the time of the stream creation.\n    var studentsStream = stream from var id in studentIds\n                            select getStudentAPI(id);\n \n    // The `getStudentAPI()` is invoked when calling the `next()` method of the constructed stream.\n    var student = studentsStream.next();\n    // The `next()` will return an error if an evaluation of a query clause results in an error.\n    while (student !is error?) {\n        io:println(student.value);\n        student = studentsStream.next();\n    }\n}\n \nfunction getStudentAPI(int studentId) returns string {\n    io:println("request to get student name API");\n    return students[studentId];\n}\n'];var wn=['import ballerina/io;\n\ntype Student record {|\n    readonly int id;\n    string name;\n    int score;\n|};\n\npublic function main() {\n    error onConflictError = error("Key Conflict", message = "record with same key exists.");\n\n    table<Student> students = table [\n            {id: 1, name: "John", score: 100},\n            {id: 2, name: "Jane", score: 150},\n            {id: 1, name: "John", score: 200}\n        ];\n\n    // The result of the following will be an error since the key `John` is duplicated.\n    map<int>|error studentScores = map from var {name, score} in students\n                                   select [name, score]\n                                   on conflict onConflictError;\n\n    io:println(studentScores);\n\n    // The value `100` of the key `John` will be replaced by the second occurrence value `200`.\n    map<int> lastRoundScore = map from var student in students\n                              select [student.name, student.score]\n                              on conflict ();\n\n    io:println(lastRoundScore);\n\n    // The result of the following will be an error since the key `1` is duplicated.\n    table<Student> key(id)|error studentScoresTable = table key(id) from var student in students\n                                                      select student\n                                                      on conflict onConflictError;\n\n    io:println(studentScoresTable);\n}\n'];var yn=['import ballerina/io;\n\ntype Student record {|\n    string name;\n    int score;\n|};\n\npublic function main() {\n    Student[] students = [\n        {name: "John", score: 100},\n        {name: "Jane", score: 150},\n        {name: "John", score: 200}\n    ];\n\n    // Create a map of the student `name` and the `score` where we replace the value of the duplicate key if the new `score` is even.\n    // The old `score` `100` of `John` will be replaced by the new `score` 200` since `replaceIfSafe()`returns `nil` for even scores.\n    map<int>|error studentScores = map from var {name, score} in students\n                                   select [name, score]\n                                   on conflict replaceIfSafe(score);\n    io:println(studentScores);\n\n    students = [\n        {name: "John", score: 100},\n        {name: "Jane", score: 150},\n        {name: "John", score: 211}\n    ];\n\n    // The result of this will be an error since the key `John` is duplicated and the `replaceIfSafe()`returns an error for odd `score` `211`.\n    map<int>|error studentScores2 = map from var {name, score} in students\n                                    select [name, score]\n                                    on conflict replaceIfSafe(score);\n    io:println(studentScores2);\n}\n\nfunction replaceIfSafe(int score) returns error? {\n    if score % 2 != 0 {\n        return error("Key Conflict", message = "Duplicate key has an odd score");\n    }\n}\n\n'];var Cn=["import ballerina/io;\n\ntype Book record {|\n    string id;\n    string name;\n|};\n\npublic function main() {\n    xml categories = xml `<categories>\n                       <category>\n                           <id>1</id>\n                           <name>cooking</name>\n                       </category>\n                       <category>\n                           <id>2</id>\n                           <name>children</name>\n                       </category>\n                       <category>\n                           <id>3</id>\n                           <name>fantasy</name>\n                       </category>\n                   </categories>`;\n\n    // Iterates through the `categories` XML sequence, constructs the `Book` records,\n    // and collects them into a table.\n    table<Book> books = from var category in categories/<category>\n                        select {\n                            id: (category/<id>).toString(),\n                            name: (category/<name>).toString()\n                        };\n\n    io:println(books);\n}\n"];var Nn=['import ballerina/io;\n\ntype Person record {|\n    string name;\n    int age;\n|};\n\npublic function main() {\n    Person[] teamA = [{name: "Alex", age: 23}, {name: "John", age: 24}];\n    Person[] teamB = [{name: "Ranjan", age: 30}, {name: "Bob", age: 28}];\n\n    var battles = from var personA in teamA\n                  from var personB in teamB\n                  select string `${personA.name} vs ${personB.name}`;\n    io:println(battles);\n}\n'];var An=['import ballerina/io;\n\ntype Person record {|\n    string first;\n    string last;\n    anydata...;\n|};\n\npublic function main() {\n    Person[] persons = [\n        {first: "Melina", last: "Kodel", "yearOfBirth": 1994},\n        {first: "Tom", last: "Riddle", "yearOfBirth": 1926}\n    ];\n\n    // A `Person` record is destructured here as a projection with the `first` and `last` fields.\n    // `{first, last}` is the mapping binding pattern. It is the same as `{first:first, last:last}`.\n    var names = from var {first, last} in persons\n                select {first, last};\n    io:println(names);\n\n    // Specify the type explicitly before the binding pattern instead of `var`.\n    names = from Person {first, last} in persons\n                 select {first, last};\n    io:println(names);\n\n    // This maps all the remaining fields of the `Person` record other than the field `first`\n    // using the rest binding pattern.\n    var lastNameAndDOB = from var {first: _, ...restDetail} in persons\n                         select restDetail;\n    io:println(lastNameAndDOB);\n}\n'];var Mn=["import ballerina/io;\n\nclass EvenNumberGenerator {\n    int i = 0;\n    public isolated function next() returns record {|int value;|}|error? {\n        self.i += 2;\n        if self.i > 10 {\n            return ();\n        }\n\n        return {value: self.i};\n    }\n}\n\npublic function main() returns error? {\n    EvenNumberGenerator evenGen = new ();\n\n    // Creates a `stream` passing an `EvenNumberGenerator` object to the `stream` constructor.\n    stream<int, error?> evenNumberStream = new (evenGen);\n\n    // Iterates the `evenNumberStream` until it returns `()`.\n    // If the stream terminates with an error, the result of the query expression will be the error.\n    int[] evenNumbers = check from var number in evenNumberStream\n                        select number;\n\n    io:println(evenNumbers);\n}\n"];var kn=['import ballerina/io;\n\npublic function main() returns error? {\n    var orders = [\n        {orderId: 1, itemName: "A", price: 23.4, quantity: 2},\n        {orderId: 1, itemName: "A", price: 20.4, quantity: 1},\n        {orderId: 2, itemName: "B", price: 21.5, quantity: 3},\n        {orderId: 1, itemName: "B", price: 21.5, quantity: 3}\n    ];\n\n    var items = from var {orderId, itemName} in orders\n        // The `group by` clause create groups for each `orderId`.\n        // The `itemName` is a non-grouping key and it becomes a sequence variable.\n        group by orderId\n        select [itemName];\n    \n    // List of items per `orderId`\n    io:println(items);\n\n    var quantities = from var {itemName, quantity} in orders\n        // The `group by` clause create groups for each `itemName`.\n        // The `quantity` is a non-grouping key and it becomes a sequence variable.\n        group by itemName\n        select {itemName, quantity: sum(quantity)};\n\n    // List of quantity per item\n    io:println(quantities);\n\n    var income = from var {price, quantity} in orders\n        let var totPrice = price*quantity\n        // The `collect` clause creates a single group and all variables become\n        // non-grouping keys\n        collect sum(totPrice);\n    \n    // Total Income from orders\n    io:println(income);\n}\n'];var Tn=["import ballerina/io;\n \npublic function main() returns error? {\n    int[] nums = [1, 2, 3, 4];\n    int[] numsTimes10 = [];\n \n    // The `from` clause works similar to a `foreach` statement.\n    check from var i in nums\n        // The `do` statement block is evaluated in each iteration.\n        do {\n            numsTimes10.push(i * 10);\n        };\n \n    io:println(numsTimes10);\n \n    // Print only the even numbers in the `nums` array.\n    // Intermediate clauses such as `let` clause, `join` clause, `order by` clause,\n    // `where clause`, and `limit` clause can also be used.\n    check from var i in nums\n        where i % 2 == 0\n        do {\n            io:println(i);\n        };\n}\n"];var En=['import ballerina/io;\n\ntype Student record {|\n    int id;\n    string name;\n|};\n \npublic function main() returns error? {\n    // As JSON is a union: `()|boolean|int|float|decimal|string|json[]|map<json>`,\n    // the following cases are allowed.\n    json n = null;\n    json i = 21;\n    json s = "str";\n    json a = [1, 2];\n    json m = {"x": n, "y": s, "z": a};\n    io:println(m);\n    json[] arr = [m, {"x": i}];\n    io:println(arr);\n \n    string rawData = "{\\"id\\": 2, \\"name\\": \\"Georgy\\"}";\n    // Get the `json` value from the string.\n    json j = check rawData.fromJsonString();\n    io:println(j);\n \n    // Access the fields of `j` using field access.\n    string name = check j.name;\n    io:println(name);\n \n    // Convert the `json` into a user-defined type.\n    Student student = check j.cloneWithType();\n    io:println(student.id);\n \n    // Convert the user-defined type to a `json`.\n    j = student;\n    io:println(j);\n}\n'];var Ln=['import ballerina/io;\nimport ballerina/lang.value;\n \npublic function main() returns error? {\n    json[] users = [\n        {\n            user: {\n                name: {\n                    firstName: "John",\n                    lastname: "Smith"\n                },\n                age: 24\n            }\n        },\n        null\n    ];\n\n    // Field access is allowed on the `json` typed variable. However, the return\n    // type would be a union of `json` and `error`.\n    json firstUserName = check users[0].user.name;\n    \n    // This is converted to `check value:ensureType(firstUserName.firstName, string)`.\n    // As the expected type is correct, the conversion is successful.\n    string firstName = check firstUserName.firstName;\n    io:println("Value of first name: " + firstName);\n    \n    // This is same as above.\n    firstName = check value:ensureType(firstUserName.firstName, string);\n    io:println("Value of first name: " + firstName);\n}\n'];var Sn=['import ballerina/io;\n\npublic function main() returns error? {\n    json user = {\n      name: {\n         firstName: "John",\n         lastname: "Smith"\n      },\n      age: 24\n    };\n\n    // Since the availability of `address` field is unknown, optional access is used\n    string? address = check user?.address;\n\n    if address is string {\n      io:println("Address: " + address);\n    }\n\n    // Optional access can be used again on fields accessed with optional access\n    string? firstName = check user?.name?.firstName;\n\n    if firstName is string {\n      io:println("First name: " + firstName);\n    }\n}\n'];var Hn=['import ballerina/io;\n \nfunction execute(json j) {\n   \tmatch j {\n   \t    // A `match` statement can be used to match maps.\n   \t    // Patterns on the left hand side in a match statement can have variable\n   \t    // parts that can be captured.\n   \t    {command: "print", amount: var x} => {\n   \t        if x is int {\n   \t            io:println("Int: ", x);\n   \t        }\n   \t    }\n\t\n   \t    _ => {\n   \t        io:println("invalid command");\n   \t    }\n   \t}\n}\n \npublic function main() {\n   \texecute({command: "print", amount: 100, status: "pending"});\n   \texecute({command: "print", amount: 10});\n   \texecute({command: "subtract", amount: 100});\n}\n'];var zn=['import ballerina/io;\n \n// Closed type.\ntype ClosedCoord record {|\n    string name;\n    [float, float] cords;\n|};\n \n// Open type can have additional `anydata` fields.\ntype OpenCoord record {\n    string name;\n    [float, float] cords;\n};\n \npublic function main() {\n    ClosedCoord a = {name: "Colombo", cords: [6.95, 79.84]};\n    // The conversion happens automatically because `a` is a subtype of `anydata`.\n    json j = a;\n    io:println(j);\n    \n    OpenCoord b = {name: "Colombo", cords: [6.94, 79.83], "area": "03"};\n    // Use `toJson()` to convert `anydata` to `json`.\n    // Usually happens automatically with closed records.\n    json k = b.toJson();\n    io:println(k);\n}\n'];var Bn=['import ballerina/io;\n \npublic function main() {\n    table<record {| int id; string name;|}> users = table [{id: 1, name: "John"}, {id: 2, name: "Sam"}];\n    // `users` is converted to a JSON array.\n    json usersAsJson = users.toJson();\n    io:println(usersAsJson is json[]);\n    io:println(usersAsJson);\n    \n    xml book = xml `<book>The Lost World</book>`;\n    // `book` is converted to a string.\n    json s = book.toJson();\n    io:println(s is string);\n    io:println(s);\n}\n'];var Zn=["import ballerina/io;\n\ntype Coord record {\n    float x;\n    float y;\n};\n\ntype Book record {\n    xml book;\n    float price;\n};\n\npublic function main() returns error? {\n    json j = {x: 1, y: 2};\n    \n    // Argument is a `typedesc` value.\n    // The static return type depends on the argument.\n    // Even if `x` and `y` are `int` in `j` they will automatically convert to `float`\n    Coord c = check j.cloneWithType(Coord);\n    io:println(c.x);\n    \n    // Argument defaulted from the context.\n    Coord d = check j.cloneWithType();\n    io:println(d.x);\n    \n    Book book = {book: xml `<book> The Treasure Island </book>`, price: 200.0};\n    \n    json bookJson = book.toJson();\n    io:println(bookJson);\n    \n    // `fromJsonWithType()` can be used to reverse conversions done by `toJson()`.\n    book = check bookJson.fromJsonWithType();\n    io:println(book);\n    \n    // Below will result in an error, because the type of the field `book` in `bookJson` is `string`.\n    Book|error result = bookJson.cloneWithType();\n    io:println(result);\n}\n"];var Vn=["import ballerina/io;\n \ntype Coord record {\n    float x;\n    float y;\n};\n \npublic function main() {\n    json j = {x: 1.0, y: 2.0};\n    \n    // Here, the inherent type of `j` is not a subtype of `Coord`. \n    // Therefore, `j` cannot be directly converted to `Coord`.\n    // Use `cloneReadOnly()` to create a read-only copy of the mutable value `j`.\n    // Then, the resulting immutable value can be casted successfully.\n    json k = j.cloneReadOnly();\n    Coord c = <Coord> k;\n    \n    io:println(c.x);\n    io:println(c.y);\n}\n"];var On=["import ballerina/http;\n\ntype Args record {|\n    decimal x;\n    decimal y;\n|};\n\ntype Response record {|\n    decimal result;\n|};\n\nlistener http:Listener ln = new (9090);\n\nservice /calc on ln {\n   // Re